sections.body:
```
TABLE files ( id BIGINT PK, owner_id BIGINT, parent_id BIGINT, -- folder tree name TEXT, size_bytes BIGINT, rev BIGINT, -- monotonic per file status ENUM, -- UPLOADING|READY|DELETED created_at TIMESTAMP
);
TABLE blocks ( file_id BIGINT, rev BIGINT, -- which version idx INT, -- ordinal within file hash CHAR(64), -- sha256 hex size INT, PRIMARY KEY (file_id, rev, idx)
);
TABLE versions ( file_id BIGINT, rev BIGINT, created_at TIMESTAMP, author_id BIGINT, PRIMARY KEY (file_id, rev)
);
TABLE acls ( file_id BIGINT, principal BIGINT, role ENUM, -- OWNER|EDITOR|VIEWER PRIMARY KEY (file_id, principal)
);
```

